def brute_force(target, wordlist, verbose=False):
    for word in wordlist:
        if verbose:
            print(f"Trying {word}...")
        if word == target:
            return word
    return None

passwords = ["123", "admin", "letmein"]
correct = "admin"
result = brute_force(correct, passwords, verbose=True)
if result:
    print(f"Cracked: {result}")
else:
    print("Not found")
